}

def extract_pdf_content(filepath):
    """Extract text from PDF"""
    try:
        # Get PDF info
        result = subprocess.run(['pdfinfo', filepath], capture_output=True, text=True, timeout=5)
        info = result.stdout

        # Extract text
        text_result = subprocess.run(['pdftotext', filepath, '-'], capture_output=True, text=True, timeout=10)
        text = text_result.stdout[:5000]  # First 5000 chars

        return info + "\n" + text
    except Exception as e:
        return f"Error: {str(e)}"

def extract_docx_content(filepath):
    """Extract text from DOCX"""
    try:
        import zipfile
        import xml.etree.ElementTree as ET

        text = []
        with zipfile.ZipFile(filepath, 'r') as zip_ref:
            xml_content = zip_ref.read('word/document.xml')
            root = ET.fromstring(xml_content)

            # Extract all text elements
            ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
            for t_elem in root.findall('.//w:t', ns):
                if t_elem.text:
                    text.append(t_elem.text)

        return ' '.join(text)[:5000]
    except Exception as e:
        return f"Error: {str(e)}"

def extract_pptx_content(filepath):
    """Extract text from PPTX"""
    try:
        import zipfile
        import xml.etree.ElementTree as ET

        text = []
        with zipfile.ZipFile(filepath, 'r') as zip_ref:
            # Get slide files
            for filename in zip_ref.namelist():
                if filename.startswith('ppt/slides/slide') and filename.endswith('.xml'):
                    xml_content = zip_ref.read(filename)
                    root = ET.fromstring(xml_content)

                    ns = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main'}
                    for t_elem in root.findall('.//a:t', ns):
                        if t_elem.text:
                            text.append(t_elem.text)

        return ' '.join(text)[:5000]
    except Exception as e:
        return f"Error: {str(e)}"

def classify_content(content):
    """Classify content based on keywords"""
    content_lower = content.lower()

    scores = {}
    for category, keywords in categories.items():
        scores[category] = sum(content_lower.count(keyword) for keyword in keywords)

    # Find category with highest score
    best_category = max(scores, key=scores.get)

    if scores[best_category] == 0:
        # If no keywords found, try to guess from file content
        if any(word in content_lower for word in ['gate', 'qubit', 'quantum']):
            return 'trapped_ion_and_qc'
        elif any(word in content_lower for word in ['language', 'text', 'model']):
            return 'LLM'
        elif any(word in content_lower for word in ['black hole', 'gravity', 'relativity']):
            return 'black_hole'
        elif any(word in content_lower for word in ['dna', 'gene', 'protein']):
            return 'DNA'
        elif any(word in content_lower for word in ['music', 'sound', 'audio']):
            return 'music_history'
        else:
            return 'LLM'  # Default

    return best_category

# Process all files
all_files = sorted([f for f in os.listdir('/root/papers/all') 
                    if f.endswith(('.pdf', '.docx', '.pptx'))])

results = []

for i, filename in enumerate(all_files, 1):
    filepath = f'/root/papers/all/{filename}'

    print(f"[{i}/{len(all_files)}] Processing: {filename}", flush=True)

    # Extract content
    if filename.endswith('.pdf'):
        content = extract_pdf_content(filepath)
    elif filename.endswith('.docx'):
        content = extract_docx_content(filepath)
    elif filename.endswith('.pptx'):
        content = extract_pptx_content(filepath)

    # Classify
    category = classify_content(content)

    results.append({
        'file': filename,
        'category': category
    })

# Print results
for result in results:
    print(f"/root/papers/all/{result['file']} -> /root/papers/{result['category']}/{result['file']}")

